def transform(grid):
    out = [row[:] for row in grid]
    cells = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    # Add a single nested 2 frame, then a 5 frame one step further inward.
    for r in range(r0 + 1, r1):
        for c in range(c0 + 1, c1):
            if r in (r0 + 1, r1 - 1) or c in (c0 + 1, c1 - 1):
                out[r][c] = 2
    for r in range(r0 + 2, r1 - 1):
        for c in range(c0 + 2, c1 - 1):
            if r in (r0 + 2, r1 - 2) or c in (c0 + 2, c1 - 2):
                out[r][c] = 5
    return out

